# Release assets are generated by tools/build-bootstrap-release.py.
param(
  [switch]$CleanupBootstrap,
  [string]$Tag = 'cc01',
  [string]$ImageMirror = '',
  [string]$NpmMirror = '',
  [string]$Share = '',
  [switch]$ShareReadOnly,
  [switch]$CchouseLoadFunctionsOnly
)
$ErrorActionPreference = 'Stop'
# The documented command launches a child Windows PowerShell. A PowerShell 7
# parent can otherwise put incompatible modules ahead of the child's built-ins.
if (-not $CchouseLoadFunctionsOnly) {
  $env:PSModulePath = Join-Path $PSHOME 'Modules'
}

$version = '@CCHOUSE_VERSION@'
$sourceHash = '@CCHOUSE_SHA256@'
$pythonVersion = '3.12.10'
$pythonUrl = "https://www.python.org/ftp/python/$pythonVersion/python-$pythonVersion-embed-amd64.zip"
$pythonHash = '4acbed6dd1c744b0376e3b1cf57ce906f9dc9e95e68824584c8099a63025a3c3'
$stage = $null
$lock = $null
$exitCode = 1

function Get-CchouseCurlPath {
  $cand = Join-Path $env:WINDIR 'System32\curl.exe'
  if (Test-Path -LiteralPath $cand -PathType Leaf) { return $cand }
  return $null
}

function Invoke-CchouseCurlDownload {
  param([string]$CurlPath, [string[]]$ArgumentList)
  $prevPref = $ErrorActionPreference
  $ErrorActionPreference = 'Continue'
  try {
    & $CurlPath @ArgumentList
    return $LASTEXITCODE
  } finally {
    $ErrorActionPreference = $prevPref
  }
}

function Invoke-CchouseRetrySleep {
  param([int]$Seconds)
  Start-Sleep -Seconds $Seconds
}

function Get-CchouseBootstrapUpArgs {
  param(
    [string]$Tag = 'cc01',
    [string]$ImageMirror = '',
    [string]$NpmMirror = '',
    [string]$Share = '',
    [switch]$ShareReadOnly
  )
  $effectiveTag = if ([string]::IsNullOrWhiteSpace($Tag)) { 'cc01' } else { $Tag.Trim() }
  $upArgs = [System.Collections.Generic.List[string]]::new()
  $upArgs.Add('up')
  $upArgs.Add('--tag')
  $upArgs.Add($effectiveTag)
  $upArgs.Add('--vm-backend')
  $upArgs.Add('virtualbox')
  $effectiveImageMirror = if (-not [string]::IsNullOrWhiteSpace($ImageMirror)) { $ImageMirror.Trim() } else { '' }
  $effectiveNpmMirror = if (-not [string]::IsNullOrWhiteSpace($NpmMirror)) { $NpmMirror.Trim() } else { '' }
  $effectiveShare = if (-not [string]::IsNullOrWhiteSpace($Share)) { $Share.Trim() } else { '' }
  if ($effectiveImageMirror) {
    $upArgs.Add('--image-mirror')
    $upArgs.Add($effectiveImageMirror)
  }
  if ($effectiveNpmMirror) {
    $upArgs.Add('--npm-mirror')
    $upArgs.Add($effectiveNpmMirror)
  }
  if ($effectiveShare) {
    $upArgs.Add('--share')
    $upArgs.Add($effectiveShare)
  }
  if ($ShareReadOnly) {
    $upArgs.Add('--read-only')
  }
  return $upArgs.ToArray()
}

function Write-CchouseCmdEntry {
  param(
    [string]$LocalAppData,
    [string]$PythonExe,
    [string]$CodeDir
  )
  $binDir = Join-Path $LocalAppData (Join-Path 'cchouse' 'bin')
  [void][IO.Directory]::CreateDirectory($binDir)
  $entry = Join-Path $binDir 'cchouse.cmd'
  $tmp = "$entry.tmp"
  $cchousePy = Join-Path $CodeDir (Join-Path 'scripts' 'cchouse.py')
  $lines = @(
    '@echo off',
    'rem Managed by cchouse',
    'setlocal',
    'set "PYTHONUTF8=1"',
    "`"$PythonExe`" -I `"$cchousePy`" %*",
    'exit /b %ERRORLEVEL%'
  )
  [IO.File]::WriteAllText($tmp, ($lines -join "`r`n") + "`r`n", [Text.UTF8Encoding]::new($false))
  Move-Item -LiteralPath $tmp -Destination $entry -Force
  return $entry
}

function Get-VerifiedArchive([string]$url, [string]$hash, [string]$destination) {
  if ((Test-Path -LiteralPath $destination -PathType Leaf) -and
      (Get-FileHash -LiteralPath $destination -Algorithm SHA256).Hash -eq $hash) { return }
  $destDir = Split-Path -Parent $destination
  if ($destDir) { [void][IO.Directory]::CreateDirectory($destDir) }
  $partial = "$destination.part"
  $fileName = [IO.Path]::GetFileName($url)
  $curl = Get-CchouseCurlPath
  $maxAttempts = 6
  $backoffs = @(2, 4, 8, 16, 30, 30)
  $useHttp11 = $false
  $downloaded = $false
  $lastErr = ''

  Write-Host "下载 $fileName..."
  for ($attempt = 1; $attempt -le $maxAttempts; $attempt++) {
    if ($curl) {
      $curlArgs = [System.Collections.Generic.List[string]]::new()
      foreach ($a in @('-f', '-L', '-C', '-', '--connect-timeout', '20', '--speed-limit', '10240', '--speed-time', '30', '--progress-bar')) {
        $curlArgs.Add($a)
      }
      if ($useHttp11) { $curlArgs.Add('--http1.1') }
      $curlArgs.Add('-o')
      $curlArgs.Add($partial)
      $curlArgs.Add($url)
      $rc = Invoke-CchouseCurlDownload -CurlPath $curl -ArgumentList $curlArgs.ToArray()
      if ($rc -eq 0 -and (Test-Path -LiteralPath $partial -PathType Leaf)) {
        $downloaded = $true
        break
      }
      $lastErr = "curl exit $rc"
      if ($rc -in @(18, 56, 92)) {
        $useHttp11 = $true
        Write-Host "下载中断（curl $rc），下次重试自动切换 --http1.1 并从断点续传（第 $attempt/$maxAttempts 次）..."
      } elseif ($rc -eq 33) {
        Remove-Item -LiteralPath $partial -Force -ErrorAction SilentlyContinue
        Write-Host "断点范围失效（curl 33），将重新下载（第 $attempt/$maxAttempts 次）..."
      } else {
        Write-Host "下载失败（curl $rc），保留已下载断点准备重试（第 $attempt/$maxAttempts 次）..."
      }
    } else {
      try {
        Invoke-WebRequest -UseBasicParsing -Uri $url -OutFile $partial
        if (Test-Path -LiteralPath $partial -PathType Leaf) {
          $downloaded = $true
          break
        }
        $lastErr = 'Invoke-WebRequest 未写出文件'
      } catch {
        $lastErr = $_.Exception.Message
        Write-Host "下载失败（$lastErr），准备重试（第 $attempt/$maxAttempts 次）..."
      }
    }
    if ($attempt -lt $maxAttempts) {
      $waitSec = $backoffs[[Math]::Min($attempt - 1, $backoffs.Length - 1)]
      Invoke-CchouseRetrySleep -Seconds $waitSec
    }
  }

  if (-not $downloaded) {
    throw "下载 $fileName 失败（已重试 $maxAttempts 次，最后错误：$lastErr）。已下载断点保留在 $partial，请检查网络/代理后重跑同一条命令续传，或传 -ImageMirror 指定镜像源。"
  }
  if ((Get-FileHash -LiteralPath $partial -Algorithm SHA256).Hash -ne $hash) {
    Remove-Item -LiteralPath $partial -Force -ErrorAction SilentlyContinue
    throw "SHA-256 校验失败：$url（已删除损坏文件，请检查网络或代理后重试）"
  }
  Move-Item -LiteralPath $partial -Destination $destination -Force
}

if ($CchouseLoadFunctionsOnly) {
  return
}

try {
  if ($env:PROCESSOR_ARCHITECTURE -ne 'AMD64') {
    throw '请在 Windows x64 的 64 位 PowerShell 中运行。'
  }
  if ($sourceHash -cnotmatch '^[0-9a-f]{64}$') {
    throw '请使用 GitHub Release 上已固定版本和 SHA-256 的引导脚本。'
  }
  $root = Join-Path $env:LOCALAPPDATA 'cchouse\bootstrap'
  Write-Host "cchouse $version 将校验并准备私有 Python 和源码，写入 $root。"
  Write-Host '随后启动 cchouse up，按提示输入节点链接。'
  $openSsh = Join-Path $env:WINDIR 'System32\OpenSSH'
  foreach ($tool in @('ssh.exe', 'ssh-keygen.exe')) {
    if (-not (Test-Path -LiteralPath (Join-Path $openSsh $tool) -PathType Leaf)) {
      throw '缺少 OpenSSH 客户端。请到 Windows 设置 → 可选功能 → 添加功能，安装 OpenSSH 客户端后重试。'
    }
  }
  $downloads = Join-Path $root 'downloads'
  $tools = Join-Path $root 'tools'
  $packages = Join-Path $root 'packages'
  [void][IO.Directory]::CreateDirectory($downloads)
  [void][IO.Directory]::CreateDirectory($tools)
  [void][IO.Directory]::CreateDirectory($packages)
  try {
    $lock = [IO.File]::Open((Join-Path $root '.prepare'), 'OpenOrCreate', 'ReadWrite', 'None')
  } catch [IO.IOException] {
    throw '另一个 cchouse 引导正在准备文件，或私有目录不可写。请确认后重试。'
  }
  $stage = Join-Path $root ('.install-' + [guid]::NewGuid().ToString('N'))
  [void][IO.Directory]::CreateDirectory($stage)

  $sourceZip = Join-Path $downloads "cchouse-$version-$sourceHash.zip"
  $sourceUrl = if ($env:CCHOUSE_BOOTSTRAP_MIRROR) {
    "$($env:CCHOUSE_BOOTSTRAP_MIRROR.TrimEnd('/'))/cchouse-$version.zip"
  } else {
    "https://github.com/nana-fox/cchouse/releases/download/$version/cchouse-$version.zip"
  }
  Get-VerifiedArchive $sourceUrl $sourceHash $sourceZip
  $pythonZip = Join-Path $downloads "python-$pythonHash.zip"
  Get-VerifiedArchive $pythonUrl $pythonHash $pythonZip
  $pythonHome = Join-Path $tools "python-$pythonVersion-embed-amd64"
  if (-not (Test-Path -LiteralPath $pythonHome -PathType Container)) {
    $pythonStage = Join-Path $stage 'python'
    Expand-Archive -LiteralPath $pythonZip -DestinationPath $pythonStage
    Move-Item -LiteralPath $pythonStage -Destination $pythonHome
  }
  $code = Join-Path $packages "$version-$($sourceHash.Substring(0,12))"
  if (-not (Test-Path -LiteralPath $code -PathType Container)) {
    Expand-Archive -LiteralPath $sourceZip -DestinationPath (Join-Path $stage 'source')
    $sourceStage = Join-Path $stage 'source\cchouse'
    if (-not (Test-Path -LiteralPath (Join-Path $sourceStage 'scripts\cchouse.py') -PathType Leaf)) {
      throw '源码包中缺少 scripts/cchouse.py。'
    }
    Move-Item -LiteralPath $sourceStage -Destination $code
  }
  $lock.Dispose()
  $lock = $null

  $env:PATH = "$openSsh;$env:PATH"
  $python = Join-Path $pythonHome 'python.exe'
  $cmdEntry = Write-CchouseCmdEntry -LocalAppData $env:LOCALAPPDATA -PythonExe $python -CodeDir $code
  Push-Location -LiteralPath $code
  try {
    $cliVersion = & $python -I 'scripts/cchouse.py' --version
    if ($LASTEXITCODE -ne 0 -or $cliVersion -cne "cchouse $version") {
      throw 'Source package version does not match the bootstrap Release.'
    }
    $upArgs = @(Get-CchouseBootstrapUpArgs -Tag $Tag -ImageMirror $ImageMirror -NpmMirror $NpmMirror -Share $Share -ShareReadOnly:$ShareReadOnly)
    Write-Host "正在启动 cchouse up（命令入口：$cmdEntry）。重跑同一条首页命令可续跑。工作目录：$code"
    & $python -I 'scripts/cchouse.py' @upArgs
    $exitCode = $LASTEXITCODE
  } finally {
    Pop-Location
  }
} catch {
  Write-Host "cchouse 引导失败：$($_.Exception.Message)"
  Write-Host '下一步：检查网络或代理状态后直接重跑同一条命令（已下载部分会自动续传）；如需换镜像源可附加 -ImageMirror <URL>。'
} finally {
  if ($lock) { $lock.Dispose() }
  if ($stage) { Remove-Item -LiteralPath $stage -Recurse -Force -ErrorAction SilentlyContinue }
  if ($CleanupBootstrap -and ([IO.Path]::GetFileName($PSCommandPath) -match '^cchouse-bootstrap-[a-f0-9]{32}\.ps1$')) {
    Remove-Item -LiteralPath $PSCommandPath -Force -ErrorAction SilentlyContinue
  }
}
exit $exitCode
